<?php
namespace App\Http\Controllers;use App\Models\{ComparisonRun,Survey};use App\Services\HistoricalComparisonService;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\View\View;
class ComparisonController extends Controller{public function index(Request $r):View{abort_unless($r->user()->can('dashboard.view'),403);$runs=ComparisonRun::with(['baseline.floor.building','followup'])->latest('calculated_at')->paginate(20);$surveys=Survey::with('floor.building')->whereHas('points.measurements',fn($q)=>$q->where('is_simulated',false))->orderByDesc('created_at')->get();return view('comparisons.index',compact('runs','surveys'));}public function store(Request $r,HistoricalComparisonService $service):JsonResponse{abort_unless($r->user()->can('reports.generate'),403);$d=$r->validate(['baseline_survey_id'=>'required|different:followup_survey_id|exists:surveys,id','followup_survey_id'=>'required|exists:surveys,id']);return response()->json($service->compare(Survey::findOrFail($d['baseline_survey_id']),Survey::findOrFail($d['followup_survey_id']),$r->user()->id),201);}public function show(Request $r,ComparisonRun $comparisonRun):JsonResponse{abort_unless($r->user()->can('dashboard.view'),403);return response()->json($comparisonRun->load(['baseline','followup']));}}
